-- ── 2. Result grid: every wiped table at 0, the kept ones as they were ───────
CREATE TEMP TABLE _reset_result (what text, rows_after bigint) ON COMMIT DROP;
DO $$
DECLARE t text; n bigint;
BEGIN
  FOREACH t IN ARRAY ARRAY['activities', 'affiliations', 'approved_contacts', 'athlete_achievements', 'athlete_claim_invites', 'athlete_equipment', 'athlete_performances', 'athlete_rivalry_display', 'athlete_vitals', 'authority_audit', 'badge_awards', 'calendar_feed_tokens', 'challenges', 'comment_likes', 'competition_entries', 'competition_entry_members', 'competition_standings', 'competitions', 'connection_suggestions', 'consent_records', 'contact_messages', 'contest_media', 'contest_media_tags', 'contest_participants', 'contest_results', 'contest_stat_lines', 'contests', 'conversation_participants', 'conversations', 'divisions', 'event_carpool_claims', 'event_carpool_offers', 'event_guests', 'event_series', 'events', 'facilities', 'follows', 'golf_hole_scores', 'golf_holes', 'golf_participant_scores', 'golf_rounds', 'golf_scorecard_data', 'group_post_media', 'group_post_participants', 'group_posts', 'guardian_invites', 'handle_history', 'help_articles', 'live_cheers', 'memberships', 'message_reactions', 'message_reports', 'messages', 'notification_preferences', 'notifications', 'org_claim_invites', 'org_join_requests', 'org_requests', 'org_site_form_submissions', 'org_site_hit_marks', 'org_site_modules', 'org_site_news', 'org_site_pages', 'org_site_revisions', 'org_site_stats_daily', 'org_sites', 'org_staff_audit', 'org_staff_invites', 'organizations', 'pending_profiles', 'performances', 'platform_admins', 'post_comments', 'post_likes', 'post_media', 'post_tags', 'posts', 'privacy_settings', 'profile_access', 'profile_access_audit', 'profile_transfers', 'profiles', 'programs', 'rate_limits', 'registration_windows', 'registrations', 'risk_signals', 'safety_settings_audit', 'sanction_grants', 'saved_posts', 'scout_shortlists', 'season_highlights', 'seasons', 'sport_event_group_members', 'sport_event_groups', 'sport_event_matches', 'sport_event_media', 'sport_event_participants', 'sport_event_rounds', 'sport_event_stat_lines', 'sport_event_teams', 'sport_events', 'sport_settings', 'sports', 'team_entries', 'teams', 'ticket_events', 'tickets', 'user_blocks', 'user_media_presets', 'user_mutes', 'venues', 'waitlist', 'workout_exercises', 'workout_routine_exercises', 'workout_routines', 'workout_sessions', 'workout_sets'] LOOP
    EXECUTE format('SELECT count(*) FROM public.%I', t) INTO n;
    INSERT INTO _reset_result VALUES ('wiped ' || t, n);
  END LOOP;
END $$;
  INSERT INTO _reset_result SELECT 'KEEP schema_migrations', count(*) FROM public.schema_migrations;
  INSERT INTO _reset_result SELECT 'KEEP reserved_handles', count(*) FROM public.reserved_handles;
  INSERT INTO _reset_result SELECT 'KEEP golf_courses', count(*) FROM public.golf_courses;
  INSERT INTO _reset_result SELECT 'KEEP golf_clubs', count(*) FROM public.golf_clubs;
  INSERT INTO _reset_result SELECT 'KEEP places', count(*) FROM public.places;
  INSERT INTO _reset_result SELECT 'KEEP place_aliases', count(*) FROM public.place_aliases;
  INSERT INTO _reset_result SELECT 'KEEP search_documents (courses)', count(*) FROM public.search_documents;
  INSERT INTO _reset_result SELECT 'search_documents non-course (expect 0)', count(*) FROM public.search_documents WHERE entity_type <> 'course';

-- Expected: every 'wiped …' row = 0; 'search_documents non-course' = 0;
-- KEEP rows unchanged (golf_courses 28973, places 69641, place_aliases
-- 247077, golf_clubs 32, reserved_handles 102, schema_migrations 244 rows).
SELECT * FROM (
  SELECT what, rows_after,
         CASE WHEN what LIKE 'wiped %' OR what LIKE '%(expect 0)' THEN CASE WHEN rows_after = 0 THEN 'OK' ELSE 'NOT EMPTY' END ELSE 'kept' END AS status
    FROM _reset_result
) r
 ORDER BY (status = 'OK'), what; -- problems and the kept tables first
